// settings.gradle.kts
include(":app", ":core:network", ":core:database", ":feature:profile", ":feature:checkout")
// a change in :feature:profile only triggers rebuilds of modules that depend on it

// :core:network/build.gradle.kts
dependencies {
    api(project(":core:model"))            // ApiResponse<Model> is exposed in public functions
    implementation(libs.okhttp)            // internal detail, hidden from consumers
    implementation(libs.kotlinx.serialization.json)
}

// :feature:cart exposes an entry point that takes callbacks, not another feature
@Composable
fun CartScreen(onCheckout: () -> Unit, onOpenProduct: (ProductId) -> Unit) { /* ... */ }

// :app wires features together
composable("cart") {
    CartScreen(
        onCheckout = { navController.navigate("checkout") },
        onOpenProduct = { id -> navController.navigate("product/${id.value}") }
    )
}
